from collections import deque

def bfs_depth_n(graph, start, target_depth):
    # Track visited nodes to avoid cycles affecting depth calculation
    # But we need to track depth levels, so use BFS properly
    visited = set([start])
    queue = deque([(start, 0)])

    depth_nodes = {0: [start]}

    while queue:
        node, depth = queue.popleft()

        if depth >= target_depth:
            continue

        for neighbor in graph.get(node, []):
            new_depth = depth + 1
            if new_depth not in depth_nodes:
                depth_nodes[new_depth] = []
            if neighbor not in depth_nodes[new_depth]:
                depth_nodes[new_depth].append(neighbor)

            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, new_depth))

    return depth_nodes

